// ═══ WRONG: one giant shared pool ═══
ExecutorService sharedPool = Executors.newFixedThreadPool(60);
// Payment calls:     sharedPool.submit(() -> callPaymentGateway());
// User requests:     sharedPool.submit(() -> getUserProfile());
// Notifications:     sharedPool.submit(() -> sendSMS());
// Payment gateway down → 60 threads blocked on gateway timeout (30s)
// → user profile requests QUEUED → notifications QUEUED → EVERYTHING DOWN!

// ═══ CORRECT: bulkhead — separate pools ═══
ThreadPoolExecutor paymentPool = new ThreadPoolExecutor(
    10, 20, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(100),
    threadFactory("payment-worker"),
    new ThreadPoolExecutor.AbortPolicy()  // reject when full → 503!
);

ThreadPoolExecutor userPool = new ThreadPoolExecutor(
    20, 30, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(200),
    threadFactory("user-worker"),
    new ThreadPoolExecutor.CallerRunsPolicy()  // back-pressure
);

ThreadPoolExecutor notifyPool = new ThreadPoolExecutor(
    5, 10, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(500),
    threadFactory("notify-worker"),
    new ThreadPoolExecutor.DiscardOldestPolicy()  // drop oldest notification
);

// Payment gateway down → paymentPool exhausted → AbortPolicy → 503 for payments
// userPool: still serving users normally! (Recommended) 
// notifyPool: still sending notifications! (Recommended) 
// ISOLATION: one failure doesn't cascade!

// ═══ MONITORING EACH POOL ═══
// paymentPool.getActiveCount()      → how many threads busy
// paymentPool.getQueue().size()     → how many tasks queued
// paymentPool.getCompletedTaskCount() → throughput
// Alert: if queue > 80% capacity → "payment pool saturated!"

