// ─── File: src/test/java/com/bank/bulkhead/BulkheadPatternTest.java ───
package com.bank.bulkhead;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class BulkheadPatternTest {

    static ThreadFactory threadFactory(String prefix) {
        AtomicInteger counter = new AtomicInteger(0);
        return r -> new Thread(r, prefix + "-" + counter.incrementAndGet());
    }

    // ═══ Bulkhead: payment failure doesn't affect user pool ═══
    @Test
    void bulkhead_isolatesFailure() throws Exception {
        // Payment pool: small, will be exhausted
        ThreadPoolExecutor paymentPool = new ThreadPoolExecutor(
            3, 3, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(2), threadFactory("payment"),
            new ThreadPoolExecutor.AbortPolicy());

        // User pool: separate, unaffected
        ThreadPoolExecutor userPool = new ThreadPoolExecutor(
            3, 3, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(10), threadFactory("user"),
            new ThreadPoolExecutor.CallerRunsPolicy());

        // Exhaust payment pool (simulate gateway down):
        for (int i = 0; i < 5; i++) {
            try {
                paymentPool.submit(() -> {
                    try { Thread.sleep(5000); } catch (InterruptedException e) { }
                });
            } catch (RejectedExecutionException e) {
                // Expected! Pool + queue full → rejected!
            }
        }

        // User pool: STILL WORKS!
        long start = System.currentTimeMillis();
        Future<String> userResult = userPool.submit(() -> "User profile loaded!");
        String result = userResult.get(5, TimeUnit.SECONDS);
        long elapsed = System.currentTimeMillis() - start;

        assertThat(result).isEqualTo("User profile loaded!");
        assertThat(elapsed).isLessThan(100);  // instant! Not affected!

        paymentPool.shutdownNow();
        userPool.shutdown();
    }

    // ═══ Shared pool: payment failure affects EVERYTHING ═══
    @Test
    void sharedPool_cascadingFailure() throws Exception {
        ThreadPoolExecutor sharedPool = new ThreadPoolExecutor(
            3, 3, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(2), threadFactory("shared"),
            new ThreadPoolExecutor.AbortPolicy());

        // Exhaust shared pool with payment tasks:
        for (int i = 0; i < 5; i++) {
            try {
                sharedPool.submit(() -> {
                    try { Thread.sleep(5000); } catch (InterruptedException e) { }
                });
            } catch (RejectedExecutionException e) { }
        }

        // User task on SAME pool → REJECTED!
        assertThatThrownBy(() -> sharedPool.submit(() -> "User profile"))
            .isInstanceOf(RejectedExecutionException.class);
        // User can't load profile because PAYMENT tasks exhausted the pool!

        sharedPool.shutdownNow();
    }

    // ═══ Pool monitoring ═══
    @Test
    void poolMonitoring() throws InterruptedException {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            5, 10, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(100), threadFactory("monitored"));

        for (int i = 0; i < 20; i++) {
            pool.submit(() -> { try { Thread.sleep(200); } catch (InterruptedException e) { } });
        }
        Thread.sleep(50);

        System.out.println("Active: " + pool.getActiveCount());
        System.out.println("Queued: " + pool.getQueue().size());
        System.out.println("Completed: " + pool.getCompletedTaskCount());
        System.out.println("Pool size: " + pool.getPoolSize());

        assertThat(pool.getActiveCount()).isGreaterThan(0);
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }
}
